#!/usr/bin/env python3
"""drug/admet_multi — auto-generated run.py (archetype=drug).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "drug"
BRAIN = "drug"
SKILL = "admet_multi"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'admet_multi', 'n_compounds': 0, 'best_score': 0.0, 'compound_csv': '', 'diagnostics': {'brain': 'drug', 'archetype': 'drug'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """ADMET-AI 1.4.0 predict — host_env=praxis-drug-admet。
    输入:smiles_list / out_csv (可选)
    输出:n_compounds / admet_csv / per_compound_summary
    """
    import os as _os
    import tempfile as _tempfile
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401

    smiles_list = payload.get("smiles_list") or ([payload.get("smiles")] if payload.get("smiles") else [])
    out_csv = payload.get("out_csv") or _tempfile.NamedTemporaryFile(suffix="_admet.csv", delete=False).name
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "n_compounds": len(smiles_list), "out_csv": out_csv}

    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "n_compounds": 0, "admet_csv": out_csv,
                "diagnostics": {**diagnostics, "dry": True}}
    if not smiles_list:
        return {"ok": False, "error": "需要 smiles_list", "diagnostics": diagnostics}

    # admet_ai / chemprop 在加载和预测时会往 stdout 打 banner/进度,污染 JSON 输出
    # (导致上层 json.loads "Expecting value")。用 redirect_stdout 把这些噪声导去 stderr,
    # import 也放进 with 块内,确保模块级 logging handler 绑定到被重定向的流;stdout 只留最终纯 JSON。
    script = (
        "import json, sys, contextlib\n"
        "with contextlib.redirect_stdout(sys.stderr):\n"
        "    from admet_ai import ADMETModel\n"
        f"    smis = {smiles_list!r}\n"
        f"    out_csv = {out_csv!r}\n"
        "    model = ADMETModel()\n"
        "    df = model.predict(smiles=smis)\n"
        "    df.to_csv(out_csv, index=True)\n"
        "    summary = []\n"
        "    for i, (idx, row) in enumerate(df.iterrows()):\n"
        "        summary.append({'smiles': smis[i] if i < len(smis) else str(idx),\n"
        "                        **{k: (float(v) if isinstance(v,(int,float)) else str(v)) for k, v in row.items()}})\n"
        "json.dump({'n_compounds': len(df), 'admet_csv': out_csv, 'per_compound_summary': summary}, sys.stdout)\n"
    )
    r = run_tool(["python3", "-c", script], timeout=int(payload.get("timeout_s", 600)))
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "admet-ai 失败"),
                "stderr": r.get("stderr", "")[-400:], "diagnostics": diagnostics}
    try:
        parsed = json.loads(r["stdout"])
    except json.JSONDecodeError as e:
        return {"ok": False, "error": f"stdout 解析失败: {e}", "stdout_head": r["stdout"][:300],
                "diagnostics": diagnostics}
    return {"ok": True, "skill_id": SKILL, **parsed, "diagnostics": diagnostics}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
